// Fonction pour obtenir une traduction
function getClipdropTranslation(key, lang) {
    if (clipdropTranslations[lang] && clipdropTranslations[lang][key]) {
        return clipdropTranslations[lang][key];
    }
    // Fallback à l'anglais
    if (clipdropTranslations.en && clipdropTranslations.en[key]) {
        return clipdropTranslations.en[key];
    }
    return null;
}

// Appliquer les traductions clipdrop
function applyClipdropTranslations(lang) {
    

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés clipdrop
        if (key && (key.startsWith('review.clipdrop.') || key.startsWith('review.common.'))) {
            const translation = getClipdropTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    
}

// Auto-appliquer quand la langue change
document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyClipdropTranslations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyClipdropTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyClipdropTranslations(currentLang);
}


